private static long insertIntoPackage(ItemStackHandler handler, ItemVariant resource, long amount) {
	long remaining = amount;
	for (int slot = 0; slot < handler.getSlots().size() && remaining > 0; slot++) {
		ItemStack existing = handler.getStackInSlot(slot);
		if (!existing.isEmpty() && !ItemStack.isSameItemSameComponents(existing, resource.toStack()))
			continue;
		int capacity = existing.isEmpty() ? resource.getItem().getDefaultMaxStackSize() : existing.getMaxStackSize() - existing.getCount();
		int moved = (int) Math.min(remaining, Math.max(0, capacity));
		if (moved == 0)
			continue;
		handler.setStackInSlot(slot, existing.isEmpty() ? resource.toStack(moved) : existing.copyWithCount(existing.getCount() + moved));
		remaining -= moved;
	}
	return amount - remaining;
}

