@Nullable
private Storage<ItemVariant> getTargetInventory() {
	Storage<ItemVariant> inventory = targetInventory.getInventory();
	if (inventory != null)
		return inventory;
	Direction facing = getBlockState().getOptionalValue(PackagerBlock.FACING).orElse(Direction.UP);
	BlockPos targetPos = worldPosition.relative(facing.getOpposite());
	if (level.getBlockEntity(targetPos) instanceof PortableStorageInterfaceBlockEntity)
		return null;
	Storage<ItemVariant> sided = ItemStorage.SIDED.find(level, targetPos, facing);
	if (sided != null)
		return sided;
	return ItemStorage.SIDED.find(level, targetPos, facing.getOpposite());
}

